// App.js
import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from "react-router-dom";

import "./App.scss";
import LoginRegisterForm from "./components/LoginRegisterContainer/LoginRegisterContainer";
import AdminCustomerContainer from "./components/AdminCustomerContainer/AdminCustomerContainer";
import UpdateProfile from "./components/UpdateProfile/UpdateProfile"; // <-- Votre nouveau composant

function App() {
  let [isUserAuthenticated, setUserAuthorization] = useState(
    sessionStorage.getItem("isUserAuthenticated") === "true" || false
  );
  let [isAdmin, setAdmin] = useState(
    sessionStorage.getItem("isAdmin") === "true" || false
  );
  let [customerId, setCustomerId] = useState(
    sessionStorage.getItem("customerId") || undefined
  );

  const setUserAuthenticatedStatus = (isAdmin, customerId) => {
    setUserAuthorization(true);
    setAdmin(isAdmin);
    setCustomerId(customerId);
  };

  const handleLogout = () => {
    sessionStorage.removeItem("isUserAuthenticated");
    sessionStorage.removeItem("isAdmin");
    sessionStorage.removeItem("customerId");

    setUserAuthorization(false);
    setAdmin(false);
    setCustomerId(undefined);
  };

  return (
    <Router>
      {/* Si pas connecté, on affiche le formulaire Login/Register */}
      {!isUserAuthenticated ? (
        <LoginRegisterForm setUserAuthenticatedStatus={setUserAuthenticatedStatus} />
      ) : (
        <>
          <div className="login-button-container">
            {/* Lien (ou bouton) vers la page "Update Profile" */}
            <Link to="/update-profile" className="login-button">
              Update Profile
            </Link>
            <button onClick={handleLogout} className="login-button">
              Logout
            </button>
          </div>

          {/* Votre container principal (admin ou client) */}
          <AdminCustomerContainer isAdmin={isAdmin} customerId={customerId} />
        </>
      )}

      {/* Définition des routes */}
      <Routes>
        {/* 
          Ici, on définit la route /update-profile pour afficher 
          le composant "UpdateProfile".
          On peut éventuellement conditionner l’accès si nécessaire. 
        */}
        <Route 
          path="/update-profile" 
          element={<UpdateProfile customerId={customerId} />} 
        />
      </Routes>
    </Router>
  );
}

export default App;
